servicePageConfig['blockchain-development'].faqs = [
  { question: 'When is blockchain appropriate instead of a traditional database?', answer: 'Blockchain is a strong candidate when multiple parties need a shared, verifiable record and no single party should control the source of truth. A traditional database is usually better for a single-owner system, high-frequency private transactions, simpler reporting, or workflows that do not require shared trust.' },
  { question: 'Do you build both public and private blockchain solutions?', answer: 'Yes. We can evaluate public networks, private ledgers, and permissioned consortium designs based on privacy, governance, throughput, identity, interoperability, and operating requirements.' },
  { question: 'How do you protect smart contracts and blockchain infrastructure?', answer: 'We use threat modeling, least-privilege access, contract unit and integration tests, adversarial scenarios, dependency review, key-management controls, monitoring, deployment gates, and documented upgrade and incident procedures.' },
  { question: 'Can blockchain connect to existing enterprise systems?', answer: 'Yes. We design API, event, indexing, identity, and data-translation layers so ledger activity can work with existing applications, ERPs, CRMs, data platforms, and reporting workflows.' },
  { question: 'Do you support blockchain maintenance after deployment?', answer: 'Yes. Maintenance can include node and application monitoring, contract or protocol upgrade planning, security reviews, incident response runbooks, performance tuning, and new integration work.' },
];

